head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gProcsCd = ""; // 사후처리상태코드
scwin.gProcsNm = ""; // 상태코드 메시지
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gEmpNo = js_emp_no; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

// 부모창(목록검색)의 접수번호
// var gAcptNo = frame.Provider("/").gAcptNo;
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd; // 처리상태
scwin.gAffProcsStatCd = $c.frame.path("../frame_head").scwin.gAffProcsStatCd; //  사후 처리상태
scwin.gDoc_LdMktTp = $c.frame.path("../frame_head").scwin.gDoc_LdMktTp;
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // 공시접수유형
scwin.gDisclsTrnsmTpCd = $c.frame.path("../frame_head").scwin.gDisclsTrnsmTpCd; // 전송구분
scwin.gDelayYn = $c.frame.path("../frame_head").scwin.gDelayYn; // 처리지연 상태여부
scwin.gFormWarnContn = $c.frame.path("../frame_head").scwin.gFormWarnContn;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 로그인 사용자정보로 공시처리가능여부 체크
        await scwin.getApprvProcButtonYN();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_AcptProcs",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_AcptProcs=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 이전단계 처리상태에 따른 버튼 생성여부
        scwin.showOptButton();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_btnshow_OnLoadCompleted
 * @description dts_btnshow 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadCompleted = function(rowcount) {
    try {
        scwin.showApprvProcButton(dts_btnshow.getCellData(1, "DUTY_PROC_YN"), dts_btnshow.getCellData(1, "GRNL_PROC_YN"), dts_btnshow.getCellData(1, "CLOSE_YN"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10108.dts_btnshow_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_btnshow_OnLoadError
 * @description dts_btnshow 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadError = async function() {
    try {
        // alert('dts_btnshow.OnFail() :' + dts_btnshow.ErrorMsg);
        await $c.win.alert("사용자 정보를 가져오는데 실패하였습니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.dts_btnshow_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_procs_stat_OnLoadCompleted
 * @description dts_procs_stat 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_procs_stat_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_procs_stat_OnLoadError
 * @description dts_procs_stat 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_procs_stat_OnLoadError = async function() {
    try {
        // alert('dts_procs_stat.OnLoadError()'+ dts_procs_stat.ErrorMsg);
        await $c.win.alert("처리상태를 가져오는데 실패하였습니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.dts_procs_stat_OnLoadError" });
    }
};

/**
 * @method
 * @name trs_AcptProcs_OnSuccess
 * @description Acpt Procs On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptProcs_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 " + scwin.gProcsNm + " 처리 되었습니다.");
        scwin.closeParentReload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.trs_AcptProcs_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_AcptProcs_OnFail
 * @description Acpt Procs On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptProcs_OnFail = async function() {
    try {
        // alert('trs_AcptProcs.OnFail() :' + trs_AcptProcs.ErrorMsg);
        await $c.win.alert(scwin.gProcsNm + " 처리에 실패하였습니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.trs_AcptProcs_OnFail" });
    }
};

/**
 * @method
 * @name trs_Review_OnSuccess
 * @description Review On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Review_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 재검토요구 처리가 되었습니다.");
        scwin.closeParentReload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.trs_Review_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Review_OnFail
 * @description Review On Fail 처리
 * @returns {Promise<void>}
