 */
scwin.trs_Review_OnFail = async function() {
    try {
        // alert('trs_Review.OnFail() :' + trs_Review.ErrorMsg);
        await $c.win.alert("재검토요구 처리에 실패하였습니다.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.trs_Review_OnFail" });
    }
};

/**
 * @method
 * @name img_approval_onclick
 * @description 「재검토요구」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_approval_onclick = async function() {
    try {
        scwin.gProcsCd = "30";
        scwin.gProcsNm = "사후승인";
        await scwin.dsclApproval(scwin.gProcsCd, scwin.gProcsNm);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.img_approval_onclick" });
    }
};

/**
 * @method
 * @name img_affreqapprov_onclick
 * @description 「사후승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_affreqapprov_onclick = async function() {
    try {
        scwin.gProcsCd = "40";
        scwin.gProcsNm = "정정요구승인";
        await scwin.dsclApproval(scwin.gProcsCd, scwin.gProcsNm);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.img_affreqapprov_onclick" });
    }
};

/**
 * @method
 * @name img_review_onclick
 * @description 「점검요구승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_review_onclick = async function() {
    try {
        scwin.gProcsCd = "01";
        scwin.gProcsNm = "재검토요구";
        await scwin.dsclApproval(scwin.gProcsCd, scwin.gProcsNm);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10108.img_review_onclick" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_close_onclick = function() {
    try {
        $c.frame.path("../").fn_CloseWin();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10108.img_close_onclick" });
    }
};

/**
 * @method
 * @name img_print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_print_onclick = function() {
    try {
        // fn_PrintFormCall();
        $c.frame.path("../frame_head").fn_PrintOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10108.img_print_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getApprvProcButtonYN
 * @description 로그인 사용자정보로 공시처리가능여부 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getApprvProcButtonYN = async function() {
    const sbmOptions = {
        id : "sbm_dts_btnshow",
        action : "/Viewer.do",
        ref : "",
        target : "dts_btnshow=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gAcptNo) {
    const sbmOptions = {
        id : "sbm_dts_procs_stat",
        action : "/DisclosureStudyAffact.do",
        ref : "",
        target : "dts_procs_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vAFF_PROCS_STAT_CD = dts_procs_stat.getCellData(1, "AFF_PROCS_STAT_CD");
    const vAFF_PROCS_STAT_NM = dts_procs_stat.getCellData(1, "AFF_PROCS_STAT_NM");
    const vAFF_PROCS_DDTM = dts_procs_stat.getCellData(1, "AFF_PROCS_DDTM");
    if (scwin.gAffProcsStatCd !== vAFF_PROCS_STAT_CD) {
        await $c.win.alert("본 공시가 " + vAFF_PROCS_DDTM + "에  이미 [" + vAFF_PROCS_STAT_NM + "] 처리가 되었습니다.");
        // fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name dsclApproval
 * @description 사후  승인 처리하기
 * @param {String} gStatCd gStatCd
 * @param {String} gStatNm gStatNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclApproval = async function(gStatCd, gStatNm) {
    if (scwin.gAcptNo === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_AcptProcs.insertRow();
    dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptProcs.setCellData(1, "AFFACT_PROCS_STAT_CD", gStatCd);
    dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    if (dts_AcptProcs.getCellData(1, "ACPT_NO") === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    const vAnswer = confirm(gStatNm + " 하시겠습니까?");
    if (vAnswer === true) {
        if (await scwin.getProcsSate(scwin.gAcptNo) === false) {
            scwin.closeParentReload();
            return false;
        } else {
            trs_AcptProcs.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_AcptProcs",
                action : "/DisclosureStudyAffact.do",
                ref : "dts_AcptProcs",
                target : "trs_AcptProcs=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showOptButton
 * @description 공동공시 유의사항
 * @returns {void}
 * @hidden N
 */
scwin.showOptButton = function() {
    // 1. 승인 및 정정요구승인, 재검토요구  버튼 생성
    if (scwin.gAffProcsStatCd === '10') {
        // 검토상태
        img_approval.show(""); // 승인 show
        img_review.show(""); // 재검토요구  show
        img_affreqapprov.hide(); // 승인 hidden

    } else if (scwin.gAffProcsStatCd === '20') {
        // 정정요구검토
        img_approval.hide(); // 승인 show
        img_affreqapprov.show(""); // 승인 hidden
        img_review.show(""); // 재검토요구  show

    } else {
        img_approval.hide(); // 승인 hidden
        img_affreqapprov.hide(); // 정정요구검토	hidden
        img_review.hide(); // 재검토요구  hidden

    }
};

/**
 * @method
 * @name showApprvProcButton
 * @description 책임자처리시 :  처리버튼 생성여부
 * @param {String} pDutyProcYn pDutyProcYn
 * @param {String} pGrnlProcYn pGrnlProcYn
 * @param {String} pCloseYn pCloseYn
 * @returns {void}
 * @hidden N
 */
scwin.showApprvProcButton = function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    if (scwin.gAcptNo !== '') {
        // 가져온접수번호가 있으면 처리함.
        // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
        // if (gJobTitle == '09' || gJobTitle == '40' || gDutyYn == 'Y' || gDutyChrg == 'Y') {
        if (scwin.gJobTitle !== '40' && (scwin.gJobTitle === '09' || scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y')) {
            // 부서장권한 제거 2013.03.26
            // 마감전일때
            if (pCloseYn === 'N') {
                if (scwin.gFormWarnContn !== "") {
                    label_WARN_CONTN.childNodes[0].innerText = scwin.gFormWarnContn;
                }

                // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
                if (pDutyProcYn === 'Y') {
                    // 패널라운드 처리
                    $c.cm.PanelToGroupBox(panel_2);
                    panel_1.show("");
                } else {
                    /*
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn == 'Y') {
                        // 패널라운드 처리
                    	PanelToGroupBox(panel_1);
                    	showObj(panel_1, true);
                    } else {
                    	showObj(panel_1, false);
                    }
                     */
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    $c.cm.PanelToGroupBox(panel_2); // 패널라운드 처리
                    panel_1.show("");
                }
            } else {
                // 마감후일때
                panel_1.hide();
            }
        } else {
            // 팀장이 아닐때
            panel_1.hide();
        }
    }
};

/**
 * @method
 * @name closeParentReload
 * @description 뷰어 닫고,  검색목록 reload
 * @returns {void}
 * @hidden N
 */
scwin.closeParentReload = function() {
    // 화면닫기
    $c.frame.path("../").fn_PvdSearch();
    $c.frame.path("../").fn_CloseWin();
};
